inline Language& Current() { static Language language = English; return language; }

// The text in the current language (shaped for Arabic); English when there is no translation.
inline const char* Tr(const char* english, Language language = Current()) {
    if (language == English) return english;
    static std::map<std::pair<int, std::string>, std::string> cache;
    const auto key = std::make_pair(int(language), std::string(english));
    const auto cached = cache.find(key);
    if (cached != cache.end()) return cached->second.c_str();
    std::string text = english;
    for (const Entry& entry : Entries())
        if (std::strcmp(entry.en, english) == 0) { if (entry.other[language - 1]) text = entry.other[language - 1]; break; }
    if (language == Arabic) text = arabic::Visual(text);
    return cache.emplace(key, std::move(text)).first->second.c_str();
}

inline const char* LanguageName(int index) { return index == Arabic ? Tr(kNames[Arabic], Arabic) : kNames[index]; }
